namespace Falcon.FSATS.ResourceManagement.Awareness;
public static class FoundationFsaPeerBinding { public const string FoundationCandidate="91da7869e7e16e943c92620ed0e8bb0fe7409459"; public const string DestinationFsaId="fsa:primary"; public const string InterfaceType="Foundation.SelfAwareness.FsaPeerInterfaceRuntime"; public static FsaPeerBindingDecision Evaluate(FsaPeerBindingRequest? r){ if(r is null||string.IsNullOrWhiteSpace(r.SourceScopeId)||string.IsNullOrWhiteSpace(r.SourceAwarenessId)||string.IsNullOrWhiteSpace(r.CandidateId)||string.IsNullOrWhiteSpace(r.EvidenceReference))return Reject("INCOMPLETE_PROVENANCE_OR_EVIDENCE"); if(!StringComparer.Ordinal.Equals(r.FoundationCandidate,FoundationCandidate))return Reject("FOUNDATION_CANDIDATE_MISMATCH"); if(!StringComparer.Ordinal.Equals(r.DestinationFsaId,DestinationFsaId))return Reject("WRONG_FSA_DESTINATION"); if(r.ContainsBusinessJudgmentAsFsaDecision)return Reject("BUSINESS_JUDGMENT_REMAINS_OUTSIDE_FSA"); if(r.AuthorityExpansionRequested)return Reject("AUTHORITY_EXPANSION_REQUEST_REQUIRES_SEPARATE_OWNER_GOVERNANCE"); if(r.OwnerSilenceTreatedAsApproval)return Reject("OWNER_SILENCE_IS_NOT_APPROVAL"); if(r.RuntimeActivationRequested||r.ProductionAdoptionRequested)return Reject("REVIEW_BINDING_DOES_NOT_GRANT_RUNTIME_OR_ADOPTION"); if(!Hash(r.CandidateSha256)||!Hash(r.EvidenceSha256))return Reject("INVALID_INTEGRITY_DIGEST"); return new(true,"DELIVERABLE_TO_FSA_REVIEW",false,false,false,false);} private static FsaPeerBindingDecision Reject(string x)=>new(false,x,false,false,false,false); private static bool Hash(string? x)=>x is {Length:64}&&x.All(c=>c is>='0'and<='9'or>='A'and<='F');}
public sealed record FsaPeerBindingRequest(string FoundationCandidate,string DestinationFsaId,string SourceScopeId,string SourceAwarenessId,string CandidateId,string CandidateSha256,string EvidenceReference,string EvidenceSha256,bool ContainsBusinessJudgmentAsFsaDecision,bool AuthorityExpansionRequested,bool OwnerSilenceTreatedAsApproval,bool RuntimeActivationRequested,bool ProductionAdoptionRequested); public sealed record FsaPeerBindingDecision(bool Accepted,string ReasonCode,bool FsaAcceptanceGranted,bool OwnerAdoptionGranted,bool RuntimeAuthorityGranted,bool BusinessAuthorityGranted);
